A general-purpose backup: permutation test
When no standard nonparametric test fits your design, a permutation test lets you build a null distribution directly from your data.

set.seed(99)
observed_diff &lt;- PlantGrowth |&gt;
  filter(group %in% c("trt1", "trt2")) |&gt;
  group_by(group) |&gt;
  summarise(m = mean(weight)) |&gt;
  summarise(diff = diff(m)) |&gt;
  pull(diff)

perm_data &lt;- PlantGrowth |&gt; filter(group %in% c("trt1", "trt2"))

n_perm &lt;- 2000
perm_diffs &lt;- replicate(n_perm, {
  shuffled &lt;- sample(perm_data$group)
  perm_data |&gt;
    mutate(group = shuffled) |&gt;
    group_by(group) |&gt;
    summarise(m = mean(weight), .groups = "drop") |&gt;
    summarise(diff = diff(m)) |&gt;
    pull(diff)
})

p_value &lt;- mean(abs(perm_diffs) &gt;= abs(observed_diff))
p_value

[1] 0.008



tibble(diff = perm_diffs) |&gt;
  ggplot(aes(diff)) +
  geom_histogram(bins = 40, fill = "steelblue", alpha = 0.7) +
  geom_vline(xintercept = observed_diff, color = "red", linewidth = 1) +
  labs(x = "Permuted mean difference (trt2 - trt1)",
       title = "Red line = observed difference") +
  theme_minimal()







Figure 1: Permutation null distribution with observed difference











